using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using Xunit;
class SuiteProgram { static int Main() {

            AssertExtensions.Throws<ArgumentOutOfRangeException>("lowSurrogate", () => char.ConvertToUtf32('\uD800', '\uD800')); // High, high
            AssertExtensions.Throws<ArgumentOutOfRangeException>("lowSurrogate", () => char.ConvertToUtf32('\uD800', '\uD7FF')); // High, non-surrogate
            AssertExtensions.Throws<ArgumentOutOfRangeException>("lowSurrogate", () => char.ConvertToUtf32('\uD800', '\u0000')); // High, non-surrogate

            AssertExtensions.Throws<ArgumentOutOfRangeException>("highSurrogate", () => char.ConvertToUtf32('\uDD00', '\uDE00')); // Low, low
            AssertExtensions.Throws<ArgumentOutOfRangeException>("highSurrogate", () => char.ConvertToUtf32('\uDC01', '\uD940')); // Low, high
            AssertExtensions.Throws<ArgumentOutOfRangeException>("highSurrogate", () => char.ConvertToUtf32('\uDF01', '\u0000')); // Low, non-surrogate

            AssertExtensions.Throws<ArgumentOutOfRangeException>("highSurrogate", () => char.ConvertToUtf32('\u0032', '\uD7FF')); // Non-surrogate, non-surrogate
            AssertExtensions.Throws<ArgumentOutOfRangeException>("highSurrogate", () => char.ConvertToUtf32('\u0000', '\u0000')); // Non-surrogate, non-surrogate

return 0; } }
// SharpForge's deliberately small test adapter. Assertions fail by throwing.

namespace Xunit
{
    public static class Assert
    {
        public static void True(bool value) { if (!value) throw new Exception("Assert.True"); }
        public static void False(bool value) { if (value) throw new Exception("Assert.False"); }
        public static void Null(object value) { if (value != null) throw new Exception("Assert.Null"); }
        public static void NotNull(object value) { if (value == null) throw new Exception("Assert.NotNull"); }
        public static void Same(object expected, object actual)
        { if (!object.ReferenceEquals(expected, actual)) throw new Exception("Assert.Same"); }
        public static void Equal<T>(T expected, T actual)
        {
            if (expected is System.Collections.IEnumerable && !(expected is string))
                throw new NotSupportedException("Shim Equal supports scalar values only, not sequence equality");
            if (!object.Equals(expected, actual)) throw new Exception("Assert.Equal");
        }
        public static T Throws<T>(Action action) where T : Exception
        {
            try { action(); }
            catch (Exception error)
            {
                if (error.GetType() != typeof(T)) throw new Exception("Assert.Throws: wrong exception type");
                return (T)error;
            }
            throw new Exception("Assert.Throws: no exception");
        }
    }
}
